using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using Object=UnityEngine.Object;
public static class RebirthCamperCorrectedBuild {
 const string P="Assets/REBIRTHCamperCorrected_20261014/rebirthCamper80s.prefab";
 const string O=RebirthCamperDefectAudit.O;
 static readonly string[] Groups={"REBIRTHCampRoofStations","REBIRTHCampInteriorStations","REBIRTHCampPowerEquipment","REBIRTHCampStairVisuals"};
 static void Mode(GameObject root,bool camp){RebirthCamperCampIntegration.SetMode(root,camp);foreach(var n in Groups)RebirthCamperDefectAudit.Find(root,n).gameObject.SetActive(camp);foreach(var c in root.GetComponentsInChildren<Collider>(true).Where(c=>c.name.StartsWith("REBIRTHInteraction_")))c.enabled=camp;}
 static string Walk(GameObject root,float h,float x,bool reverse){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.transform.position=new Vector3(0,-.15f,-4);g.transform.localScale=new Vector3(10,.3f,10);var p=new GameObject("Proxy");var cc=p.AddComponent<CharacterController>();cc.height=h;cc.radius=h==1.8f?.35f:.28665f;cc.center=Vector3.up*h/2;cc.skinWidth=.08f;cc.stepOffset=.1f;cc.slopeLimit=50;cc.minMoveDistance=0;p.transform.position=new Vector3(x,reverse?.99f:.09f,reverse?-1.6f:-5.5f);Physics.SyncTransforms();for(int i=0;i<650;i++){cc.Move(new Vector3(0,-.03f,reverse?-.012f:.012f));if(reverse?p.transform.position.z< -5.4f:p.transform.position.z> -1.6f)break;}bool pass=reverse?p.transform.position.z< -5.4f:p.transform.position.z> -2f;string s="h="+h+" x="+x+" reverse="+reverse+" final="+p.transform.position+" PASS="+pass;Object.DestroyImmediate(p);Object.DestroyImmediate(g);if(!pass)throw new Exception(s);return s;}
 public static void Build(){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var root=Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(P));Mode(root,true);var log=new List<string>();foreach(float h in new[]{1.72f,1.8f})foreach(float x in new[]{-.04f,0,.04f})foreach(bool reverse in new[]{false,true})log.Add(Walk(root,h,x,reverse));File.WriteAllLines(O+"/qualified-entry.txt",log);Mode(root,false);Object.DestroyImmediate(root);Directory.CreateDirectory(O+"/Bundle");var result=RebirthAssetBundlePackaging.BuildAssetBundles(O+"/Bundle",new[]{new AssetBundleBuild{assetBundleName="rebirth_camper80s.unity3d",assetNames=new[]{P}}},BuildAssetBundleOptions.ChunkBasedCompression,BuildTarget.StandaloneWindows64);if(!result)throw new Exception("Build failed");File.WriteAllText(O+"/build-receipt.txt",DateTime.UtcNow.ToString("O")+" Unity source bundle built; requires localized .1 stepOffset runtime. Not game tested.");}
 public static void Verify(){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var b=AssetBundle.LoadFromFile(O+"/Bundle/rebirth_camper80s.unity3d");if(!b)throw new Exception("Bundle missing");var root=Object.Instantiate(b.LoadAsset<GameObject>("rebirthCamper80s"));var targets=root.GetComponentsInChildren<Collider>(true).Where(c=>c.name.StartsWith("REBIRTHInteraction_")).ToArray();if(targets.Length!=20||targets.Any(c=>!c.isTrigger||c.enabled))throw new Exception("Targets");foreach(var n in Groups)if(RebirthCamperDefectAudit.Find(root,n).gameObject.activeSelf)throw new Exception("Travel default");if(RebirthCamperDefectAudit.Find(root,"shadow_plane").GetComponent<Renderer>().enabled)throw new Exception("Shadow plane");if(!RebirthCamperDefectAudit.Find(root,"Fitted rooftop guardrails").gameObject.activeInHierarchy)throw new Exception("Rails");Mode(root,true);var log=new List<string>();foreach(float h in new[]{1.72f,1.8f})foreach(bool rev in new[]{false,true})log.Add(Walk(root,h,0,rev));
 RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=new Color(.65f,.65f,.65f);var sun=new GameObject().AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=1.1f;sun.transform.rotation=Quaternion.Euler(45,-35,0);var cam=new GameObject().AddComponent<Camera>();cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.12f,.14f,.16f);cam.nearClipPlane=.01f;cam.orthographic=true;foreach(var r in root.GetComponentsInChildren<Renderer>(true).Where(r=>r.name=="body"||r.name=="camper_body")){var mp=new MaterialPropertyBlock();mp.SetFloat("_PatternEnabled",1);r.SetPropertyBlock(mp);}foreach(bool camp in new[]{false,true}){Mode(root,camp);string n=camp?"final-camp":"final-travel";Save(cam,new Vector3(-5,3.8f,-6),new Vector3(0,1.7f,-1),3.4f,n+"-left");Save(cam,new Vector3(5,3.8f,-6),new Vector3(0,1.7f,-1),3.4f,n+"-right");}Mode(root,true);Save(cam,new Vector3(0,1.75f,-5.8f),new Vector3(0,1.75f,-2),1.5f,"final-door-stairs");cam.orthographic=false;cam.fieldOfView=70;Save(cam,new Vector3(0,2.25f,-3.2f),new Vector3(0,1.8f,-.5f),1,"final-interior");log.Add("20 targets, Travel defaults, permanent rails, shadow plane disabled, reopened bundle entry/exit PASS. Unity only; no in-game validation.");File.WriteAllLines(O+"/verified-bundle.txt",log);}
 static void Save(Camera c,Vector3 eye,Vector3 target,float size,string n){c.transform.position=eye;c.transform.LookAt(target);c.orthographicSize=size;var rt=new RenderTexture(1600,1200,24);c.targetTexture=rt;c.Render();RenderTexture.active=rt;var im=new Texture2D(1600,1200,TextureFormat.RGB24,false);im.ReadPixels(new Rect(0,0,1600,1200),0,0);im.Apply();File.WriteAllBytes(O+"/Renders/"+n+".png",im.EncodeToPNG());c.targetTexture=null;RenderTexture.active=null;Object.DestroyImmediate(rt);Object.DestroyImmediate(im);}
}
